from pathlib import Path

p = Path('index.html')
s = p.read_text(encoding='utf-8')
marker = 'let purchasePlanSelection=new Set();'
start = s.index(marker) if marker in s else s.index('function renderPurchasePlan(){')
end = s.index('function renderPurchases(){', start)
new = r'''let purchasePlanSelection=new Set();
function syncPurchasePlanSelection(rows){const valid=new Set((rows||[]).map(x=>String(x.productId)));for(const id of [...purchasePlanSelection])if(!valid.has(String(id)))purchasePlanSelection.delete(id)}
function togglePurchasePlanSelection(productId,checked){const key=decodeURIComponent(String(productId||''));if(checked)purchasePlanSelection.add(key);else purchasePlanSelection.delete(key);updatePurchasePlanBulkControls()}
function selectAllPurchasePlan(){const rows=purchaseRecommendations();purchasePlanSelection=new Set(rows.map(x=>String(x.productId)));renderPurchasePlan()}
function clearPurchasePlanSelection(){purchasePlanSelection.clear();renderPurchasePlan()}
function updatePurchasePlanBulkControls(){const count=purchasePlanSelection.size,btn=document.getElementById('purchasePlanBulkBtn'),counter=document.getElementById('purchasePlanBulkCount');if(btn){btn.disabled=count===0;btn.textContent=count?`Общая закупка · ${count} поз.`:'Общая закупка'}if(counter)counter.textContent=count?`Выбрано: ${count}`:'Ничего не выбрано'}
function renderPurchasePlan(){const box=document.getElementById('purchasePlan');if(!box)return;const rows=purchaseRecommendations();syncPurchasePlanSelection(rows);if(!rows.length){purchasePlanSelection.clear();box.innerHTML='<div class="item purchase-plan-empty"><b>На 25 дней товара хватает</b><div class="muted" style="margin-top:5px">Остаток и уже заказанные поставки с учётом этапа доставки покрывают период ожидания.</div></div>';return}const total=rows.reduce((sum,x)=>sum+x.qty,0),lines=rows.map(x=>{const estimate=x.unitCost>0?` · примерно ${fmt(x.estimatedCost)} по прошлой цене ${fmt(x.unitCost)}/шт.`:' · прошлой закупочной цены нет',stageQty=s=>x.timeline.filter(t=>t.status===s).reduce((n,t)=>n+t.qty,0),stageDays=s=>{const a=x.timeline.filter(t=>t.status===s).map(t=>t.days);return a.length?Math.min(...a):null},parts=[],fw=stageQty('to_forwarder'),me=stageQty('to_me'),wh=stageQty('at_warehouse');if(fw)parts.push(`до склада поставщика ${fw} шт. · примерно ${stageDays('to_forwarder')} дн. до вас`);if(me)parts.push(`едет ко мне ${me} шт. · примерно ${stageDays('to_me')} дн.`);if(wh)parts.push(`уже на складе ${wh} шт.`);const delivery=parts.length?`<div class="muted" style="margin-top:4px">В доставке: ${parts.join(' · ')}</div>`:'',risk=Number.isFinite(x.nextArrivalDays)&&x.stockDays<x.nextArrivalDays?`<div class="muted" style="margin-top:4px;color:#b45309">⚠ Текущего остатка хватит на ${x.stockDays.toFixed(1)} дн., ближайшая поставка примерно через ${x.nextArrivalDays} дн.</div>`:'',key=String(x.productId),checked=purchasePlanSelection.has(key)?' checked':'';return `<div class="purchase-line"><input type="checkbox" class="purchase-plan-check" style="width:24px;height:24px;flex:none;margin-top:3px"${checked} onchange="togglePurchasePlanSelection('${encodeURIComponent(key)}',this.checked)"><div class="grow"><b>${esc(x.product.name)}</b><div class="muted">Свободно ${x.available} · всего в доставке/на складе ${x.inbound} · заказы ${x.daily.toFixed(1)}/день · общий запас ${x.days.toFixed(1)} дн.${estimate}</div>${delivery}${risk}</div><div class="right"><button class="btn dark" onclick="openRecommendedPurchase('${encodeURIComponent(key)}')">Купить ${x.qty}</button></div></div>`}).join('');const selected=purchasePlanSelection.size;box.innerHTML=`<div class="item purchase-plan"><div class="order-head"><div class="grow"><div class="name">Надо купить на следующие 25 дней</div><div class="muted">Доставка: до 5 дней до склада поставщика + до 20 дней до вас. ${rows.length} поз. · ${total} шт.</div></div><span class="badge warn">${rows.length}</span></div><div class="purchase-lines">${lines}</div><div class="row" style="margin-top:14px;align-items:center"><button class="btn" type="button" onclick="selectAllPurchasePlan()">Выбрать все</button><button class="btn" type="button" onclick="clearPurchasePlanSelection()">Снять</button><span id="purchasePlanBulkCount" class="muted" style="margin-left:auto">${selected?`Выбрано: ${selected}`:'Ничего не выбрано'}</span></div><button id="purchasePlanBulkBtn" class="btn dark full" type="button" ${selected?'':'disabled'} onclick="openSelectedRecommendedPurchase()">${selected?`Общая закупка · ${selected} поз.`:'Общая закупка'}</button></div>`}
function openRecommendedPurchase(encodedProductId){const productId=decodeURIComponent(String(encodedProductId||'')),row=purchaseRecommendations().find(x=>String(x.productId)===productId);if(!row)return alert('Рекомендация уже изменилась. Обновите список закупки.');window.pendingPurchaseRecommendations=[{productId:row.productId,qty:row.qty,unitCost:row.unitCost}];window.pendingPurchaseHint={name:row.product.name,qty:row.qty,unitCost:row.unitCost,estimatedCost:row.estimatedCost};openModal('purchase')}
function openSelectedRecommendedPurchase(){const current=purchaseRecommendations(),selected=current.filter(x=>purchasePlanSelection.has(String(x.productId)));if(!selected.length)return alert('Отметьте товары для общей закупки.');window.pendingPurchaseRecommendations=selected.map(x=>({productId:x.productId,qty:x.qty,unitCost:x.unitCost}));window.pendingPurchaseHint=null;openModal('purchase')}
'''
s = s[:start] + new + s[end:]
p.write_text(s, encoding='utf-8')
print('patched bulk purchase selection')
